/**
 * Reset the third person store, clearing listeners.
 * Call this on Physics.dispose() to prevent memory leaks across HMR reloads.
 */
export function resetThirdPersonStore(): void;
/**
 * Minimum camera offset scaler (for zoom).
 * @type {number}
 */
export const offsetScalerMin: number;
/**
 * Maximum camera offset scaler (for zoom).
 * @type {number}
 */
export const offsetScalerMax: number;
export const subscribeThirdPersonStore: any;
export const getThirdPersonStore: any;
export const setThirdPersonStore: any;
/**
 * Available camera mode identifiers.
 *
 * @constant
 * @type {Object}
 * @property {string} FIRST_PERSON - First-person camera mode
 * @property {string} THIRD_PERSON - Third-person locked camera mode
 * @property {string} THIRD_PERSON_FREE - Third-person free orbit mode
 * @property {string} BIRD_VIEW - Bird's-eye view mode
 */
export const CAMERA_MODES: any;
